mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.m2m m2m,
  ttokssaemdb.branch branch,
  ttokssaemdb.member member

  AND m2m.branchid = branch.branchid
  AND m2m.memberid = member.memberid

    AND m2m.branchid = #{session_branchid}


    AND (
      m2m.question LIKE #{likeQuery}
      OR m2m.answer LIKE #{likeQuery}
      OR member.membername LIKE #{likeQuery}
    )

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberid, member.membername, m2m.m2mid, m2m.question, m2m.answer, m2m.status, DATE_FORMAT(m2m.regdate, '%Y-%m-%d %H:%i:%s') regdate, m2m.answerid, DATE_FORMAT(m2m.findate, '%Y-%m-%d %H:%i:%s') findate FROM ttokssaemdb.m2m m2m, ttokssaemdb.branch branch, ttokssaemdb.member member
AND m2m.branchid = branch.branchid AND m2m.memberid = member.memberid
AND m2m.branchid = #{session_branchid}
AND ( m2m.question LIKE #{likeQuery} OR m2m.answer LIKE #{likeQuery} OR member.membername LIKE #{likeQuery} )
m2m.m2mid m2m.status m2m.regdate m2m.findate DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}

SELECT branch.branchid, branch.branchname, member.memberid, member.membername, m2m.m2mid, m2m.question, m2m.answer, m2m.status, DATE_FORMAT(m2m.regdate, '%Y-%m-%d %H:%i:%s') regdate, m2m.answerid, DATE_FORMAT(m2m.findate, '%Y-%m-%d %H:%i:%s') findate FROM ttokssaemdb.m2m m2m, ttokssaemdb.branch branch, ttokssaemdb.member member
AND m2m.branchid = branch.branchid AND m2m.memberid = member.memberid
AND m2m.m2mid = #{m2mid}

mapper.update:
UPDATE ttokssaemdb.m2m
SET
  answer = #{answer},
  status = #{status},
  findate = now(),
  answerid = #{answerid}

  AND branchid = #{branchid}
  AND m2mid = ${m2mid}
